  var TYPES = {"radical-substitution":{"label":"ラジカル置換","summary":"光や熱で結合が切れて生じたラジカルを経由し、炭素上の水素が別の原子や基で置き換わる。置き換わる水素は1種類とは限らないため、生成物が複数生じうる。","schematic":"C–H ＋ X–X → C–X ＋ H–X","count":1},"substitution":{"label":"置換","summary":"炭素についた基が、別の基でそのまま置き換わる。炭素骨格は変化しない。","schematic":"R–Y ＋ Z → R–Z ＋ Y","count":6},"addition":{"label":"付加","summary":"二重結合や三重結合の一部が開き、そこへ別の原子・基が結合する。不飽和結合の数が減る。","schematic":"C=C ＋ A–B → C–C(A)(B)","count":9},"hydrogenation":{"label":"水素付加","summary":"多重結合に水素が付加し、結合次数が下がる。条件によって部分還元（アルキン→アルケン）にも完全還元（アルケン→アルカン）にも進む。","schematic":"C=C ＋ H–H → C–C(H)(H)（アルキンは部分還元で C=C へ）","count":6},"hydration":{"label":"水和","summary":"水が付加して −OH が生じる。アルケンからアルコールをつくる経路の代表例。","schematic":"C=C ＋ H–OH → C–C(H)(OH)","count":4},"elimination":{"label":"脱離","summary":"隣り合う炭素から原子や基が取れて、二重結合・三重結合が新しくできる。脱水と脱ハロゲン化水素をまとめて扱う。","schematic":"C–C(H)(OH) → C=C ＋ H–OH","count":3},"oxidation":{"label":"酸化","summary":"酸素が入る、または水素が取れる。アルコール → アルデヒド → カルボン酸のように段階を経て進むことがある。","schematic":"R–CH₂OH → R–CHO → R–COOH","count":24},"reduction":{"label":"還元","summary":"水素が入る、または酸素が取れる。カルボニル基がアルコールに、ニトロ基がアミノ基になる例がある。","schematic":">C=O ＋ 2[H] → >CH–OH","count":6},"esterification":{"label":"エステル化","summary":"カルボン酸とアルコールから水が取れて −COO− 結合ができる。縮合の一種で、生成物はエステルと水。","schematic":"R–COOH ＋ R′–OH ⇄ R–COO–R′ ＋ H₂O","count":16},"hydrolysis":{"label":"加水分解","summary":"水が反応して結合が切れる。エステル・アミド・糖のグリコシド結合・ペプチド結合で起こる。","schematic":"R–COO–R′ ＋ H₂O → R–COOH ＋ R′–OH","count":20},"saponification":{"label":"けん化","summary":"エステルをアルカリで加水分解すると、カルボン酸塩とアルコールが生じる。油脂（トリグリセリド）では脂肪酸の塩とグリセリンが生じ、塩はセッケンとして働く。","schematic":"油脂 ＋ 3NaOH → 3 脂肪酸ナトリウム ＋ グリセリン","count":5},"neutralization":{"label":"中和","summary":"酸と塩基が反応して塩ができる。弱酸の塩に強酸を加えると、弱酸が遊離する場合がある。","schematic":"R–COOH ＋ NaOH → R–COONa ＋ H₂O","count":12},"nitration":{"label":"ニトロ化","summary":"ベンゼン環の水素がニトロ基（−NO₂）で置き換わる。置換の位置は環についている他の基の影響を受ける。","schematic":"Ar–H ＋ HNO₃ → Ar–NO₂ ＋ H₂O","count":2},"sulfonation":{"label":"スルホン化","summary":"ベンゼン環の水素がスルホ基（−SO₃H）で置き換わる。スルホ基は水に溶けやすい性質を与える。","schematic":"Ar–H ＋ H₂SO₄ → Ar–SO₃H ＋ H₂O","count":1},"aromatic-substitution":{"label":"芳香族置換","summary":"ベンゼン環の水素が別の原子・基で置き換わる。環の共役（芳香族性）は保たれる。","schematic":"Ar–H ＋ E–X → Ar–E ＋ H–X","count":3},"diazotization":{"label":"ジアゾ化","summary":"第一級芳香族アミンのアミノ基がジアゾニウム塩（−N₂⁺）に変わる。生じたジアゾニウム塩は反応性が高く、低温で扱う。","schematic":"Ar–NH₂ ＋ NaNO₂ ＋ 2HCl → Ar–N₂⁺Cl⁻ ＋ 2H₂O ＋ NaCl","count":1},"coupling":{"label":"カップリング","summary":"ジアゾニウム塩が芳香族化合物と結合し、アゾ基（−N=N−）を介して2つの環がつながる。色素の合成に使われる。","schematic":"Ar–N₂⁺ ＋ Ar′–H → Ar–N=N–Ar′ ＋ H⁺","count":1},"condensation":{"label":"縮合","summary":"2分子以上から水などの小さな分子が取れて、新しい結合ができる。エステル化やアミド化もこの仲間。","schematic":"A–H ＋ B–OH → A–B ＋ H₂O","count":6},"peptide-bond":{"label":"ペプチド結合","summary":"アミノ酸のカルボキシ基と別のアミノ酸のアミノ基から水が取れて −CO–NH− 結合ができる。縮合の一種。","schematic":"H₂N–R–COOH ＋ H₂N–R′–COOH → H₂N–R–CO–NH–R′–COOH ＋ H₂O","count":3},"acetylation":{"label":"アセチル化","summary":"−OH や −NH₂ の水素がアセチル基（−COCH₃）で置き換わる。エステル化・アミド化の一種。","schematic":"R–OH ＋ (CH₃CO)₂O → R–OCOCH₃ ＋ CH₃COOH","count":3},"metal-reaction":{"label":"金属との反応","summary":"アルコールやフェノールの −OH の水素が金属で置き換わり、水素が発生する。","schematic":"2R–OH ＋ 2Na → 2R–ONa ＋ H₂","count":2},"carboxylation":{"label":"カルボキシ化","summary":"フェノールの塩に二酸化炭素を作用させ、環にカルボキシ基を導入する。酸を加えると遊離のヒドロキシ酸になる。","schematic":"Ar–ONa ＋ CO₂ → Ar(COONa)–OH","count":1},"addition-polymerization":{"label":"付加重合","summary":"二重結合が開いて単量体どうしが次々につながる。主鎖には単量体の骨格がそのまま並ぶ。","schematic":"n C=C → –(C–C)ₙ–","count":12},"condensation-polymerization":{"label":"縮重合","summary":"多官能性の単量体から、水などの小さな分子が取れながら高分子になる。単一のアミノ酸の自己縮合のような場合も含む。主鎖には結合の変化が残る。","schematic":"n A–B ＋ n C–D → –(A–D)ₙ– ＋ 小分子","count":7},"ring-opening-polymerization":{"label":"開環重合","summary":"環状の単量体の環が開き、そのままつながって高分子になる。","schematic":"n 環状単量体 → –(開いた単位)ₙ–","count":1},"polymerization":{"label":"重合","summary":"単量体が繰り返し結合して高分子になる。付加重合・縮重合・開環重合などの総称として使う。","schematic":"n 単量体 → –(繰り返し単位)ₙ–","count":1},"fermentation":{"label":"発酵","summary":"酵素のはたらきで糖が分解され、アルコールや二酸化炭素などが生じる。生体由来の触媒を使う反応。","schematic":"C₆H₁₂O₆ → 2C₂H₅OH ＋ 2CO₂","count":1},"isomerization":{"label":"異性化","summary":"原子の数と種類は変えずに、原子の配置が変わる。シス-トランスの変換が代表例。","schematic":"シス体 ⇄ トランス体","count":1},"decomposition":{"label":"分解","summary":"1つの化合物が2つ以上の物質に分かれる。加熱や触媒によって結合が切れる。","schematic":"A–B → A ＋ B","count":2},"precipitation":{"label":"沈殿生成","summary":"特定の構造が金属イオンなどと結合して、溶けにくい化合物として析出する。構造の確認に使われる。","schematic":"R–C≡C–H ＋ Ag⁺ → R–C≡C–Ag↓ ＋ H⁺","count":2}};
